<span class="line"><span style="color:#F97583;">    status</span><span style="color:#E1E4E8;"> ENUM(</span><span style="color:#9ECBFF;">&#39;Active&#39;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&#39;Inactive&#39;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&#39;Deleted&#39;</span><span style="color:#E1E4E8;">) </span><span style="color:#F97583;">DEFAULT</span><span style="color:#9ECBFF;"> &#39;Active&#39;</span><span style="color:#E1E4E8;">,</span></span>
