<span class="line"><span style="color:#F97583;">    INDEX</span><span style="color:#E1E4E8;"> idx_status_price (</span><span style="color:#F97583;">status</span><span style="color:#E1E4E8;">, price),                </span><span style="color:#6A737D;">-- 状态+价格</span></span>
